import { Component } from '@angular/core';
import { Router } from '@angular/router';

import { inject } from '@angular/core';
import { environment } from '../../environments/environment';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './home.component.html',
  styleUrl: './home.component.css'
})
export class HomeComponent {
  private router = inject(Router);
  appName = environment.app_name;
  activeCard = {
    inversion: false,
    aguas: false
  };
  additionalInstructions = {
    inversion: false,
    aguas: false
  };
  showFundamentoLegal = false;
  anioActual = new Date().getFullYear();
  navigateToRegister() {
    this.router.navigate(['/auth/register']);
  }

  navigateToLogin() {
    this.router.navigate(['/auth/login']);
  }

  toggleCard(cardName: keyof typeof this.activeCard) {
    this.activeCard[cardName] = !this.activeCard[cardName];
  }

  toggleAdditional(cardName: keyof typeof this.additionalInstructions) {
    this.additionalInstructions[cardName] = !this.additionalInstructions[cardName];
  }

  toggleFundamentoLegal() {
    this.showFundamentoLegal = !this.showFundamentoLegal;
  }
}